function getData(query) {
    fetch('/api/avatar/chat', {
        method: 'POST',
        headers: {
            'Content-Type': 'application/json',
        },
        body: JSON.stringify({
            user: openid,
            role: role,
            query: query
        }),
    })
        .then(function (response) {
            if (response.ok) {
                return response.json();
            } else {
                throw new Error('Failed to get avatar response.');

            }
        }).then(function (data) {

        // console.debug(data)
        console.debug(data['audio'])
        console.debug(data['text'])

        _data=data;
        let clip=null;
        let clipAction = null;
        try {
            clip = createAnimation(blendData, audio_offsets, 'Wolf3D_Head');
            if(clip === undefined){
                clip = null;
            }
            clipAction = mixer.clipAction(clip);
        }catch (e) {
            console.error('Failed to create animation',e);
            clip = null;
        }

        if(clipAction != null)
            clipAction.setLoop((THREE.LoopRepeat))
        audioProcesser = new Howl({
            src: data['audio'],
            // autoplay:true,
            // onplayerror: function(id,error) {
            //     console.error('audio play error',id,error);
            //     audioProcesser.once('unlock', function() {
            //         console.debug('audio play unlocked');
            //         audioProcesser.play();
            //     });
            // }
        })
        // audioProcesser.once('load', function(){
        //     console.debug('audio loaded,start playing')
        //     audioProcesser.play();
        // });
        audioProcesser.on("play", function () {
            console.log('play')
            switchToSpeakPose();
            isPlaying = true;
            if(clipAction != null) {
                clipAction.paused = !isPlaying;
                clipAction.play();
            }
         })
        audioProcesser.on("playerror", function (id,error) {
            console.error('audio play error',id,error)
            console.log(data['audio'])
         })
        audioProcesser.on("loaderror", function (id,error) {
            console.error('audio load error',id,error)
            console.log(data['audio'])
         })
        audioProcesser.on("pause", function () {
            console.log('paused')
            isPlaying = false;
            if(clipAction != null) {
                clipAction.paused = !isPlaying;
            }
            playButton.innerHTML = '<i class="material-icons">play_arrow</i>';
        })
        audioProcesser.on("end", function () {
            console.log('ended')
            isPlaying = false;
            if(clipAction != null) {
                clipAction.stop();
            }
            playButton.innerHTML = '<i class="material-icons">play_arrow</i>';
            switchToIdlePose();
             connectWebSocket();
        })
        subtitles = data['text'];
        console.log(subtitles)
        showSubtitles();


        playClips();

        if(subtitles==="面试已结束，感谢您的参与！"){
            console.log("end")
            //等待2秒，跳转到其他页面
            setTimeout(() => {
        window.location.href = "/applicant/dashboard"; // 替换为目标页面地址
    }, 5000);

        }


    }).catch(function (error) {
        console.error(error)
        alert('出错啦!\n' + error.message);
    });
}

function switchToIdlePose(){
    if(clipAction_idle_head)
        clipAction_idle_head.play()
    if(clipAction_idle_eye)
        clipAction_idle_eye.play()
}
function switchToSpeakPose(){
    if(clipAction_idle_head)
        clipAction_idle_head.stop()
    if(clipAction_idle_eye)
        clipAction_idle_eye.stop()
}
function createAnimation(blendData,audio_offsets,name) {

    if (blendData.length !== 0) {
        let animation = []

        for (let i = 0; i < 69; i++) {
            animation.push([]);
        }

       let time = [];
        let start = 0, tot = 0, i = 0, j = 0;
        for (i = 0; i < audio_offsets.length - 1; i++) {
            let offset1 = audio_offsets[i], offset2 = audio_offsets[i + 1];
            let offset_delta = offset2 - offset1;  //取出两段语音变化的偏移量 单位毫秒
            let cnt = Math.ceil(offset_delta / (1 / fps * 1000));  //根据偏移量时间从帧数组中取出对应个数的帧(1个数组为1帧 约 1 / 60 * 1000 ms)
            // console.log("取出" + cnt + "个");
            for (j = start; j < Math.min(start + cnt, blendData.length); j++) {
                // console.log("start", j);
                let blend_arr = blendData[j]['blendshapes'];

                for (let k = 0; k < blend_arr.length - 3; k++) {

                    animation[mapper[k]].push(blend_arr[k]);
                }

                if (j === start + cnt - 1) {
                    // 在取出的帧数组的最后一个数组的关键帧时间上加上一定量的偏移(偏移量 = offset_delta / 25000, ps:试出来的)
                    tot += offset_delta / 25000;
                    time.push(tot);
                }
                else {
                    time.push(tot);
                }
                tot += (1 / fps);
                // console.log(time);
            }
            start = start + cnt;
        }
        //如果帧数组中还有帧的话，按每次1/60的偏移量添加到time数组
        if (j < blendData.length) {
            for (let i = j; i < blendData.length; i++) {
                let blend_arr = blendData[i]['blendshapes'];
                for (let k = 0; k < blend_arr.length - 3; k++) {
                    animation[mapper[k]].push(blend_arr[k]);
                }
                time.push(tot);
                tot += (1 / fps);
            }
        }

        let tracks = [];

        for (let i = 0; i < blendData[0].blendshapes.length - 3; i++) {
            let track = new THREE.NumberKeyframeTrack(`${name}.morphTargetInfluences[${mapper[i]}]`, time, animation[mapper[i]],THREE.InterpolateSmooth);
            tracks.push(track);
        }

        const clip = new THREE.AnimationClip('animation', -1, tracks);

        return clip;
    }
}

