function getWebSocketUrl() {
    // 请求地址根据语种不同变化
    let url = "wss://iat-api.xfyun.cn/v2/iat";
    const host = "iat-api.xfyun.cn";
    const apiKey = API_KEY;
    const apiSecret = API_SECRET;
    const date = new Date().toGMTString();
    const algorithm = "hmac-sha256";
    const headers = "host date request-line";
    const signatureOrigin = `host: ${host}\ndate: ${date}\nGET /v2/iat HTTP/1.1`;
    const signatureSha = CryptoJS.HmacSHA256(signatureOrigin, apiSecret);
    const signature = CryptoJS.enc.Base64.stringify(signatureSha);
    const authorizationOrigin = `api_key="${apiKey}", algorithm="${algorithm}", headers="${headers}", signature="${signature}"`;
    const authorization = btoa(authorizationOrigin);
    url = `${url}?authorization=${authorization}&date=${date}&host=${host}`;
    return url;
}


function toBase64(buffer) {
    let binary = "";
    const bytes = new Uint8Array(buffer);
    const len = bytes.byteLength;
    for (let i = 0; i < len; i++) {
        binary += String.fromCharCode(bytes[i]);
    }
    return window.btoa(binary);
}

function connectWebSocket() {
    const webSocketUrl = getWebSocketUrl();
    if ("WebSocket" in window) {
        ws = new WebSocket(webSocketUrl);
    } else if ("MozWebSocket" in window) {
        ws = new MozWebSocket(webSocketUrl);
    } else {
        alert("浏览器不支持WebSocket");
        return;
    }
    resultText = "";
    resultTextTemp = "";
    ws.onopen = e => {
        while (ws.readyState===WebSocket.CONNECTING){
            // console.debug('connecting');
            null;//wait for ws readystate changed
        }
        recorder.start({
            sampleRate: 16000,
            frameSize: 1280,
        });
        let params = {
            common: {
                app_id: APP_ID,
            },
            business: {
                language: "zh_cn",
                domain: "iat",
                accent: "mandarin",
                vad_eos: 5000,
                dwa: "wpgs",
            },
            data: {
                status: 0,
                format: "audio/L16;rate=16000",
                encoding: "raw",
            },
        };
        ws.send(JSON.stringify(params));

        isMuted=false;
        imgWaveform.style.display = 'flex';
        muteButton.innerHTML = '<i class="material-icons">mic</i>';
        countdown();

    }
    ws.onmessage = e => {
        renderResult(e.data);
    }

    ws.onerror = (e) => {
        console.error(e);
         isMuted=true;
        imgWaveform.style.display = 'none';
        muteButton.innerHTML = '<i class="material-icons">mic_off</i>';
    };
    ws.onclose = (e) => {
        isMuted=true;
        imgWaveform.style.display = 'none';
        muteButton.innerHTML = '<i class="material-icons">mic_off</i>';
        recorder.stop();
        if (countdownInterval) {
            clearInterval(countdownInterval);
        }
        if(MsgToSend.length>0) {
            console.log('preparing send msg to server...')
            getData(MsgToSend);
            MsgToSend = "";
        }
    };
}

recorder.onFrameRecorded = ({isLastFrame, frameBuffer}) => {
    if (ws.readyState === ws.OPEN) {
        ws.send(
            JSON.stringify({
                data: {
                    status: isLastFrame ? 2 : 1,
                    format: "audio/L16;rate=16000",
                    encoding: "raw",
                    audio: toBase64(frameBuffer),
                }
            })
        );
        if (isLastFrame) {
            ws.close()
        }
    }
}
function countdown() {
    let seconds = 60;
    countdownInterval = setInterval(() => {
        seconds = seconds - 1;
        if (seconds <= 0) {
            clearInterval(countdownInterval);
            recorder.stop();
        } else {
            // btnStart.innerText = `录音中 (${seconds}s)`;
        }
    }, 1000);
}

function renderResult(resultData) {
    let jsonData = JSON.parse(resultData);
    console.log(jsonData);
    if (jsonData.data && jsonData.data.result) {
        let data = jsonData.data.result;
        let str = "";
        let ws = data.ws;
        for (let i = 0; i < ws.length; i++) {
            str = str + ws[i].cw[0].w;
        }
        if (data.pgs) {
            if (data.pgs === "apd") {
                resultText = resultTextTemp;
            }
            resultTextTemp = resultText + str;
        } else {
            resultText = resultText + str;
        }
        MsgToSend = resultTextTemp || resultText || "";
        console.debug(MsgToSend)
    }

    if (jsonData.code === 0 && jsonData.data.status === 2) {
        console.log(jsonData);
        ws.close();
    }
    if (jsonData.code !== 0) {
        ws.close();
        console.log(jsonData);
    }
}


function d2r(degrees) {
    let radians = (degrees * Math.PI) / 180;
    return radians;
}
function GetQ(arr) {
    let result = [];
    for (let i = 0; i < arr.length; i++) {
        let q = new THREE.Quaternion().setFromEuler(arr[i]);
        result.push(...q.toArray());
    }

    return result;
}

function GetE(headRotation) {
    let e_arr = [
        new THREE.Euler(headRotation.x, headRotation.y, headRotation.z),  // 0

        new THREE.Euler(d2r(-18.72), d2r(-2.58), d2r(0.02)),
        new THREE.Euler(d2r(-18.63), d2r(-2.06), d2r(1.61)),
        new THREE.Euler(d2r(-17.05), d2r(-2.06), d2r(1.61)),
        new THREE.Euler(d2r(-18.63), d2r(-2.06), d2r(1.61)),
        new THREE.Euler(d2r(-20.01), d2r(-2.06), d2r(1.61)),
        new THREE.Euler(d2r(-20.03), d2r(0.09), d2r(0.2)),
        new THREE.Euler(d2r(-20.03), d2r(1.29), d2r(0.2)),
        new THREE.Euler(d2r(-19.46), d2r(1.29), d2r(0.2)),
        new THREE.Euler(d2r(-20.53), d2r(1.29), d2r(0.2)),
        new THREE.Euler(d2r(-20.53), d2r(1.99), d2r(0.2)),
        new THREE.Euler(d2r(-20.53), d2r(3.9), d2r(1.76)),
        new THREE.Euler(d2r(-19.54), d2r(3.9), d2r(1.76)),
        new THREE.Euler(d2r(-20.04), d2r(3.9), d2r(1.76)),
        new THREE.Euler(d2r(-19.81), d2r(-3.2), d2r(-1.61)),
        new THREE.Euler(d2r(-20.81), d2r(-3.2), d2r(-1.61)),
        new THREE.Euler(d2r(-23.49), d2r(-3.37), d2r(-3.05)),
        new THREE.Euler(d2r(-19.92), d2r(1.39), d2r(-2.69)),
        new THREE.Euler(d2r(-20.01), d2r(4.08), d2r(-0.90)),
        new THREE.Euler(d2r(-20.01), d2r(6.47), d2r(-0.5)),
        new THREE.Euler(d2r(-18.82), d2r(-0.68), d2r(-0.97)),
        new THREE.Euler(d2r(-15.25), d2r(-0.68), d2r(-0.97)),
        new THREE.Euler(d2r(-18.82), d2r(-0.68), d2r(-0.97)),
        new THREE.Euler(d2r(-15.25), d2r(-0.68), d2r(-0.97)),
        new THREE.Euler(d2r(-18.82), d2r(-0.68), d2r(-0.97)),

        new THREE.Euler(headRotation.x, headRotation.y, headRotation.z),  // 16

    ];
    return e_arr;
}
